INSERT INTO `ai_chat_message` (`id`, `session_id`, `role`, `content`, `model`, `metadata`, `create_time`, `update_time`, `is_deleted`) VALUES (52, '4190212', 'assistant', '我需要更多的信息来帮助您实现排序功能。请问您希望对什么类型的数据进行排序？例如，是数字列表、字符串列表还是其他类型的数据？另外，您希望使用哪种编程语言来实现这个功能？', NULL, NULL, '2025-09-02 19:23:24', '2025-09-02 19:23:24', 0);
