  KEY `idx_job_edge_parent_from` (`from_node_id`,`job_parent_id`)
) ENGINE=InnoDB AUTO_INCREMENT=20173 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='任务边';

